def reference(vectors):
    WALK_LEFT, WALK_RIGHT, FALL_LEFT, FALL_RIGHT, DIG_LEFT, DIG_RIGHT, SPLAT = range(7)
    state = WALK_LEFT
    fall_count = 0
    results = []
    for v in vectors:
        areset = v['areset']
        bl = v['bump_left']
        br = v['bump_right']
        g = v['ground']
        d = v['dig']
        if areset:
            state = WALK_LEFT
            fall_count = 0
            results.append({'walk_left':1,'walk_right':0,'aaah':0,'digging':0})
            continue
        # outputs from current state
        if state == WALK_LEFT:
            out = {'walk_left':1,'walk_right':0,'aaah':0,'digging':0}
        elif state == WALK_RIGHT:
            out = {'walk_left':0,'walk_right':1,'aaah':0,'digging':0}
        elif state in (FALL_LEFT, FALL_RIGHT):
            out = {'walk_left':0,'walk_right':0,'aaah':1,'digging':0}
        elif state in (DIG_LEFT, DIG_RIGHT):
            out = {'walk_left':0,'walk_right':0,'aaah':0,'digging':1}
        else:
            out = {'walk_left':0,'walk_right':0,'aaah':0,'digging':0}
        results.append(out)
        # next state
        if state == WALK_LEFT:
            if g == 0:
                state = FALL_LEFT
                fall_count = 0
            elif d == 1:
                state = DIG_LEFT
            elif bl == 1 or br == 1:
                state = WALK_RIGHT
        elif state == WALK_RIGHT:
            if g == 0:
                state = FALL_RIGHT
                fall_count = 0
            elif d == 1:
                state = DIG_RIGHT
            elif bl == 1 or br == 1:
                state = WALK_LEFT
        elif state == FALL_LEFT:
            if g == 1:
                if fall_count > 20:
                    state = SPLAT
                else:
                    state = WALK_LEFT
            else:
                fall_count += 1
        elif state == FALL_RIGHT:
            if g == 1:
                if fall_count > 20:
                    state = SPLAT
                else:
                    state = WALK_RIGHT
            else:
                fall_count += 1
        elif state == DIG_LEFT:
            if g == 0:
                state = FALL_LEFT
                fall_count = 0
        elif state == DIG_RIGHT:
            if g == 0:
                state = FALL_RIGHT
                fall_count = 0
        # SPLAT stays
    return results
